from collections import Counter
import os,re
def split(d,n):
    s=[];prev=-99
    for x in d+[n]:
        if prev>=0 and x>prev: s.append((prev+1,x))
        prev=x
    return s
def comps(pts):
    cells=set(pts); out=[]
    while cells:
        p=next(iter(cells)); st=[p]; cells.discard(p); comp=[]
        while st:
            r,c=st.pop(); comp.append((r,c))
            for dr,dc_ in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc_)
                if n in cells: cells.discard(n); st.append(n)
        out.append(comp)
    return out
def solve(g,thresh=3):
    H,W=len(g),len(g[0])
    divr=[i for i,r in enumerate(g) if len(set(r))==1]
    divc=[j for j in range(W) if len(set(g[i][j] for i in range(H)))==1]
    dc=g[divr[0]][0]
    bg=Counter(v for r in g for v in r if v!=dc).most_common(1)[0][0]
    rs=split(divr,H); cs=split(divc,W)
    bands=[(r0,r1) for r0,r1 in zip(rs[:-1],rs[1:])]+[(rs[-1][-1],H)]
    cols=[(c0,c1) for c0,c1 in zip(cs[:-1],cs[1:])]+[(cs[-1][-1],W)]
    # find selected band/col block with largest component >= thresh
    best=None
    for r0,r1 in bands:
        for c0,c1 in cols:
            pts={(rr,cc) for rr in range(r0,r1) for cc in range(c0,c1) if g[rr][cc]!=bg and g[rr][cc]!=dc}
            szs=[len(c) for c in comps(pts)]
            m=max(szs) if szs else 0
            if m>=thresh and (best is None or m>best[0]):
                best=(m,r0,r1,c0,c1)
    _,r0,r1,c0,c1=best
    oc=Counter(g[rr][cc] for rr in range(r0,r1) for cc in range(c0,c1) if g[rr][cc]!=dc).most_common()
    col=oc[0][0] if oc else bg
    out=[row[:] for row in g]
    for r2 in range(r0,r1):
        for c2 in range(c0,c1):
            out[r2][c2]=col
    return out
